SELECT?course
WHERE {
  ?course a ns1:course.
  ?course ns1:has_credits?credits.
  FILTER NOT EXISTS {?other a ns1:course.?other ns1:has_credits?otherCredits.FILTER (?otherCredits >?credits) }
}
LIMIT 1

